from dataclasses import dataclass

from .gnb.networkaddress import NetworkAddress
from .testpc import TestPc


class DiagnosticCard:
    pass


@dataclass
class Remote:
    """
    A class representing a remote connection. Primary UART is to be picked as a convention (first in the list)

    Attributes:
        addr (NetworkAddress): The network address of the remote connection.
        port (int): The port number of the remote TCP connection.
    """
    addr: NetworkAddress
    port: int


@dataclass
class Local:
    """
    A class representing a local connection. Primary UART is to be picked as a convention (first in the list)

    Attributes:
        port (str): The port number of the local connection. e.g. COM1, COM2, /dev/ttyUSB0, /dev/ttyUSB1
    """
    port: str


@dataclass
class LMI(DiagnosticCard):
    """
    Local Management Interface (LMI) is intended to be used for Nokia internal test access in RFM/RRH/MAA type products
     e.g. during HW bring-up, in Production Test, repair services, SW-debugging and for SW-R&D purposes
    The product requirement for the LMI interface can be found in DOORS (BTS_OPS_290).

    This object represents an LMI interface connector e.g. 093193A.X03

    Attributes:
        product_code (str): The product code of the LMI interface connector.
        host (TestPc): The host PC where the LMI interface is connected.
    """
    product_code: str
    host: TestPc  # Typical use case - btslog run on uepc, limitation on IP
    uart_mapping: list[Local]  # mapping device : UART e.g. COM1 : UART1


@dataclass
class SerialOverHost(DiagnosticCard):
    """
    MUMIN - Modest UART mgmt interface
    A class representing a 'UART to USB' variant where UART is accessible over a local host to which SSH connection needs
    to be created first.

    Attributes:
        host (TestPc): The host PC where the UART to USB connection is established.
        uart_mapping (list[Local]): A list of local connections mapping COM port to UART.
    """
    host: TestPc
    uart_mapping: list[Local]  # mapping device : UART e.g. COM1 : UART1


@dataclass
class SerialOverTcp(DiagnosticCard):
    """
    MUMIN - Modest UART mgmt interface
    A class representing a 'UART to ETH' variant which is exposing a remote TCP port on which UART is accessible

    Attributes:
        uart_mapping (list[Remote]): A list of local connections mapping TCP port to UART.
    """
    uart_mapping: list[Remote]  # mapping TCP port : UART e.g. 192.168.1.90:5001 : UART1
